import{_ as d,a0 as i,w as r,s as l,I as a,x as s,a1 as o,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Fedora 中的容器技术：systemd-nspawn | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 中的容器技术：systemd-nspawn | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 中的容器技术：systemd-nspawn | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 中的容器技术：systemd-nspawn | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160621 Container technologies in Fedora - systemd-nspawn","title":"Fedora 中的容器技术：systemd-nspawn","tag":"201607","desc":""},"relativePath":"201607/20160621 Container technologies in Fedora - systemd-nspawn.md","filePath":"[post].md"}'),c={name:"201607/20160621 Container technologies in Fedora - systemd-nspawn.md"};function h(m,e,b,g,u,f){const t=i("Link");return r(),l("div",null,[e[18]||(e[18]=a("h1",{id:"fedora-中的容器技术-systemd-nspawn",tabindex:"-1"},[s("Fedora 中的容器技术：systemd-nspawn "),a("a",{class:"header-anchor",href:"#fedora-中的容器技术-systemd-nspawn","aria-label":"Permalink to “Fedora 中的容器技术：systemd-nspawn”"},"​")],-1)),e[19]||(e[19]=a("p",null,[s("欢迎来到“Fedora 中的容器技术”系列！本文是该系列文章中的第一篇，它将说明你可以怎样使用 Fedora 中各种可用的容器技术。本文将学习 "),a("code",null,"systemd-nspawn"),s(" 的相关知识。")],-1)),e[20]||(e[20]=a("h3",{id:"容器是什么",tabindex:"-1"},[s("容器是什么？ "),a("a",{class:"header-anchor",href:"#容器是什么","aria-label":"Permalink to “容器是什么？”"},"​")],-1)),a("p",null,[e[1]||(e[1]=s("一个容器就是一个用户空间实例，它能够在与托管容器的系统（叫做宿主系统）相隔离的环境中运行一个程序或者一个操作系统。这和 ",-1)),e[2]||(e[2]=a("code",null,"chroot",-1)),e[3]||(e[3]=s(" 或 ",-1)),o(t,{href:"https://en.wikipedia.org/wiki/Virtual_machine"},{default:n(()=>[...e[0]||(e[0]=[s("虚拟机",-1)])]),_:1}),e[4]||(e[4]=s(" 的思想非常类似。运行在容器中的进程是由与宿主操作系统相同的内核来管理的，但它们是与宿主文件系统以及其它进程隔离开的。",-1))]),e[21]||(e[21]=p(`<h3 id="什么是-systemd-nspawn" tabindex="-1">什么是 systemd-nspawn？ <a class="header-anchor" href="#什么是-systemd-nspawn" aria-label="Permalink to “什么是 systemd-nspawn？”">​</a></h3><p>systemd 项目认为应当将容器技术变成桌面的基础部分，并且应当和用户的其余系统集成在一起。为此，systemd 提供了 <code>systemd-nspawn</code>，这款工具能够使用多种 Linux 技术创建容器。它也提供了一些容器管理工具。</p><p><code>systemd-nspawn</code> 和 <code>chroot</code> 在许多方面都是类似的，但是前者更加强大。它虚拟化了文件系统、进程树以及客户系统中的进程间通信。它的吸引力在于它提供了很多用于管理容器的工具，例如用来管理容器的 <code>machinectl</code>。由 <code>systemd-nspawn</code> 运行的容器将会与 systemd 组件一同运行在宿主系统上。举例来说，一个容器的日志可以输出到宿主系统的日志中。</p><p>在 Fedora 24 上，<code>systemd-nspawn</code> 已经从 systemd 软件包分离出来了，所以你需要安装 <code>systemd-container</code> 软件包。一如往常，你可以使用 <code>dnf install systemd-container</code> 进行安装。</p><h3 id="创建容器" tabindex="-1">创建容器 <a class="header-anchor" href="#创建容器" aria-label="Permalink to “创建容器”">​</a></h3><p>使用 <code>systemd-nspawn</code> 创建一个容器是很容易的。假设你有一个专门为 Debian 创造的应用，并且无法在其它发行版中正常运行。那并不是一个问题，我们可以创造一个容器！为了设置容器使用最新版本的 Debian（现在是 Jessie），你需要挑选一个目录来放置你的系统。我暂时将使用目录 <code>~/DebianJessie</code>。</p><p>一旦你创建完目录，你需要运行 <code>debootstrap</code>，你可以从 Fedora 仓库中安装它。对于 Debian Jessie，你运行下面的命令来初始化一个 Debian 文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debootstrap --arch=amd64 stable ~/DebianJessie</span></span></code></pre></div><p>以上默认你的架构是 x86_64。如果不是的话，你必须将架构的名称改为 <code>amd64</code>。你可以使用 <code>uname -m</code> 得知你的机器架构。</p><p>一旦设置好你的根目录，你就可以使用下面的命令来启动你的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemd-nspawn -bD ~/DebianJessie</span></span></code></pre></div><p>容器将会在数秒后准备好并运行，当你试图登录时就会注意到：你无法使用你的系统上任何账户。这是因为 <code>systemd-nspawn</code> 虚拟化了用户。修复的方法很简单：将之前的命令中的 <code>-b</code> 移除即可。你将直接进入容器的 root 用户的 shell。此时，你只能使用 <code>passwd</code> 命令为 root 设置密码，或者使用 <code>adduser</code> 命令添加一个新用户。一旦设置好密码或添加好用户，你就可以把 <code>-b</code> 标志添加回去然后继续了。你会进入到熟悉的登录控制台，然后你使用设置好的认证信息登录进去。</p><p>以上对于任意你想在容器中运行的发行版都适用，但前提是你需要使用正确的包管理器创建系统。对于 Fedora，你应使用 DNF 而非 <code>debootstrap</code>。想要设置一个最小化的 Fedora 系统，你可以运行下面的命令，要将“/absolute/path/”替换成任何你希望容器存放的位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf --releasever=24 --installroot=/absolute/path/ install systemd passwd dnf fedora-release</span></span></code></pre></div><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2016/06/Screenshot-from-2016-06-17-15-04-14.png" alt=""></p><h3 id="设置网络" tabindex="-1">设置网络 <a class="header-anchor" href="#设置网络" aria-label="Permalink to “设置网络”">​</a></h3><p>如果你尝试启动一个服务，但它绑定了你宿主机正在使用的端口，你将会注意到这个问题：你的容器正在使用和宿主机相同的网络接口。幸运的是，<code>systemd-nspawn</code> 提供了几种可以将网络从宿主机分开的方法。</p><h4 id="本地网络" tabindex="-1">本地网络 <a class="header-anchor" href="#本地网络" aria-label="Permalink to “本地网络”">​</a></h4><p>第一种方法是使用 <code>--private-network</code> 标志，它默认仅创建一个回环设备。这对于你不需要使用网络的环境是非常理想的，例如构建系统和其它持续集成系统。</p><h4 id="多个网络接口" tabindex="-1">多个网络接口 <a class="header-anchor" href="#多个网络接口" aria-label="Permalink to “多个网络接口”">​</a></h4><p>如果你有多个网络接口设备，你可以使用 <code>--network-interface</code> 标志给容器分配一个接口。想要给我的容器分配 <code>eno1</code>，我会添加选项 <code>--network-interface=eno1</code>。当某个接口分配给一个容器后，宿主机就不能同时使用那个接口了。只有当容器彻底关闭后，宿主机才可以使用那个接口。</p><h4 id="共享网络接口" tabindex="-1">共享网络接口 <a class="header-anchor" href="#共享网络接口" aria-label="Permalink to “共享网络接口”">​</a></h4><p>对于我们中那些并没有额外的网络设备的人来说，还有其它方法可以访问容器。一种就是使用 <code>--port</code> 选项。这会将容器中的一个端口定向到宿主机。使用格式是 <code>协议:宿主机端口:容器端口</code>，这里的协议可以是 <code>tcp</code> 或者 <code>udp</code>，<code>宿主机端口</code> 是宿主机的一个合法端口，<code>容器端口</code> 则是容器中的一个合法端口。你可以省略协议，只指定 <code>宿主机端口:容器端口</code>。我通常的用法类似 <code>--port=2222:22</code>。</p><p>你可以使用 <code>--network-veth</code> 启用完全的、仅宿主机模式的网络，这会在宿主机和容器之间创建一个虚拟的网络接口。你也可以使用 <code>--network-bridge</code> 桥接二者的连接。</p><h3 id="使用-systemd-组件" tabindex="-1">使用 systemd 组件 <a class="header-anchor" href="#使用-systemd-组件" aria-label="Permalink to “使用 systemd 组件”">​</a></h3><p>如果你容器中的系统含有 D-Bus，你可以使用 systemd 提供的实用工具来控制并监视你的容器。基础安装的 Debian 并不包含 <code>dbus</code>。如果你想在 Debian Jessie 中使用 <code>dbus</code>，你需要运行命令 <code>apt install dbus</code>。</p><h4 id="machinectl" tabindex="-1">machinectl <a class="header-anchor" href="#machinectl" aria-label="Permalink to “machinectl”">​</a></h4><p>为了能够轻松地管理容器，systemd 提供了 <code>machinectl</code> 实用工具。使用 <code>machinectl</code>，你可以使用 <code>machinectl login name</code> 登录到一个容器中、使用 <code>machinectl status name</code>检查状态、使用 <code>machinectl reboot name</code> 启动容器或者使用 <code>machinectl poweroff name</code> 关闭容器。</p><h3 id="其它-systemd-命令" tabindex="-1">其它 systemd 命令 <a class="header-anchor" href="#其它-systemd-命令" aria-label="Permalink to “其它 systemd 命令”">​</a></h3><p>多数 systemd 命令，例如 <code>journalctl</code>, <code>systemd-analyze</code> 和 <code>systemctl</code>，都支持使用 <code>--machine</code> 选项来指定容器。例如，如果你想查看一个名为 “foobar” 的容器的日志，你可以使用 <code>journalctl --machine=foobar</code>。你也可以使用 <code>systemctl --machine=foobar status service</code> 来查看运行在这个容器中的服务状态。</p><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2016/06/Screenshot-from-2016-06-17-15-09-25.png" alt=""></p><h3 id="和-selinux-一起工作" tabindex="-1">和 SELinux 一起工作 <a class="header-anchor" href="#和-selinux-一起工作" aria-label="Permalink to “和 SELinux 一起工作”">​</a></h3><p>如果你要使用 SELinux 强制模式（Fedora 默认模式），你需要为你的容器设置 SELinux 环境。想要那样的话，你需要在宿主系统上运行下面两行命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ semanage fcontext -a -t svirt_sandbox_file_t &quot;/path/to/container(/.*)?&quot;</span></span>
<span class="line"><span>$ restorecon -R /path/to/container/</span></span></code></pre></div><p>确保使用你的容器路径替换 “/path/to/container”。对于我的容器 &quot;DebianJessie&quot;，我会运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ semanage fcontext -a -t svirt_sandbox_file_t &quot;/home/johnmh/DebianJessie(/.*)?&quot;</span></span>
<span class="line"><span>$ restorecon -R /home/johnmh/DebianJessie/</span></span></code></pre></div><hr>`,37)),a("p",null,[e[6]||(e[6]=s("via: ",-1)),o(t,{href:"https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/"},{default:n(()=>[...e[5]||(e[5]=[s("https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=s("作者：",-1)),o(t,{href:"https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/"},{default:n(()=>[...e[7]||(e[7]=[s("John M. Harris, Jr.",-1)])]),_:1}),e[11]||(e[11]=s(" 译者：",-1)),o(t,{href:"https://github.com/chrisleegit"},{default:n(()=>[...e[8]||(e[8]=[s("ChrisLeeGit",-1)])]),_:1}),e[12]||(e[12]=s(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[9]||(e[9]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=s("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[s("LCTT",-1)])]),_:1}),e[16]||(e[16]=s(" 原创编译，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[s("Linux中国",-1)])]),_:1}),e[17]||(e[17]=s(" 荣誉推出",-1))])])}const x=d(c,[["render",h]]);export{w as __pageData,x as default};
